USE CATALOG dcp_synth;
CREATE OR REPLACE VIEW `04_presentation`.vw_cio_service_trend AS SELECT metric_date,metric_name,metric_value,target_value,status FROM `01_bronze`.platform_sla_metrics;
CREATE OR REPLACE VIEW `04_presentation`.vw_cio_control_posture AS SELECT control_domain,score_pct,assessed_at FROM `01_bronze`.control_posture;
CREATE OR REPLACE VIEW `04_presentation`.vw_cio_resource_mix AS SELECT resource_type,utilization_pct,cost_share_pct,metric_time FROM `01_bronze`.platform_resources;
CREATE OR REPLACE VIEW `04_presentation`.vw_cio_adoption AS SELECT experience,eligible_users,active_users,ROUND(100.0*active_users/NULLIF(eligible_users,0),2) adoption_pct,metric_date FROM `01_bronze`.dashboard_adoption;
CREATE OR REPLACE VIEW `04_presentation`.vw_cio_release_readiness AS SELECT product_id,maturity,readiness_status,owner,next_action FROM `01_bronze`.release_readiness;
CREATE OR REPLACE VIEW `04_presentation`.vw_platform_source_health AS SELECT source_id,source_name,domain,freshness_minutes,freshness_status,lifecycle_status FROM `01_bronze`.source_health;
CREATE OR REPLACE VIEW `04_presentation`.vw_platform_pipeline_runs AS SELECT pipeline_run_id,source_id,started_at,duration_seconds,status FROM `01_bronze`.pipeline_runs;
CREATE OR REPLACE VIEW `04_presentation`.vw_platform_exception_queue AS SELECT exception_id,source_id,exception_type,severity,status,owner,next_action,opened_at FROM `01_bronze`.platform_exceptions;
CREATE OR REPLACE VIEW `04_presentation`.vw_platform_recovery AS SELECT layer,recovery_state,rto_hours,rpo_hours,tested_at FROM `01_bronze`.recovery_state;
CREATE OR REPLACE VIEW `04_presentation`.vw_regulatory_readiness AS SELECT r.submission_id,r.required_items,r.complete_items,r.readiness_pct,r.exception_count,s.product_id,s.market,s.authority,s.workflow_stage,s.risk_status,s.owner FROM `01_bronze`.submission_readiness r LEFT JOIN `03_gold`.dp19_regulatory_submission_master s USING(submission_id);
CREATE OR REPLACE VIEW `04_presentation`.vw_compliance_evidence AS SELECT control_id,domain,evidence_status,assessed_date,owner FROM `05_compliance`.evidence;
CREATE OR REPLACE VIEW `04_presentation`.vw_patient_event_log AS SELECT event_id,patient_id,event_type,event_time,quantity,sync_status FROM `01_bronze`.mydiabete_events;
CREATE OR REPLACE VIEW `04_presentation`.vw_patient_alerts AS SELECT alert_id,patient_id,alert_type,status,created_at FROM `01_bronze`.patient_alerts;
CREATE OR REPLACE VIEW `04_presentation`.vw_patient_report_sharing AS SELECT sharing_id,patient_id,report_id,recipient_type,sharing_status,shared_at FROM `01_bronze`.report_sharing;
